namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (!TryGetDeficit(item, out int deficit))
                continue;

            int orderQuantity = CalculateOrderQuantity(deficit, season);
            if (orderQuantity <= 0 || string.IsNullOrEmpty(item.Sku))
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, orderQuantity);
            plan.Add(DescribeOrder(item.Sku, orderQuantity, placed));
        }

        return plan;
    }

    private static bool TryGetDeficit(StockItem item, out int deficit)
    {
        deficit = 0;
        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return false;

        deficit = item.ReorderPoint - available;
        return true;
    }

    private static int CalculateOrderQuantity(int deficit, int season)
    {
        int orderQuantity;
        if (deficit <= 0)
            orderQuantity = 0;
        else if (deficit < 10)
            orderQuantity = 10;
        else if (deficit < 100)
            orderQuantity = deficit;
        else
            orderQuantity = deficit + 50;

        if (season == 4 && orderQuantity > 0)
            orderQuantity = (int)(orderQuantity * 1.5);
        else if (season == 1)
            orderQuantity /= 2;

        return orderQuantity;
    }

    private static string DescribeOrder(string sku, int orderQuantity, bool placed)
    {
        if (placed && orderQuantity > 200)
            return $"{sku}:LARGE:{orderQuantity}";

        return placed
            ? $"{sku}:{orderQuantity}"
            : $"{sku}:FAILED";
    }
}
